NEW_FILES = {'alarm_service.dart': "import 'dart:convert';\nimport 'package:flutter/material.dart';\nimport 'package:flutter/services.dart';\nimport 'package:shared_preferences/shared_preferences.dart';\nimport '../screens/alarm_ring_screen.dart';\n\n/// 아침 알람 하나 (시간 · 요일 · 깨울 소리)\nclass ParanAlarm {\n  bool enabled;\n  int hour;\n  int minute;\n  List<int> days; // 1=월 … 7=일, 비어 있으면 한 번만\n  String kind; // music_all · music_fav · playlist · radio · nature\n  String? refId; // 재생목록 id · 자연 이름\n  String label; // 화면에 보여줄 이름 (예: 즐겨찾기 섞어 듣기)\n  Map<String, dynamic>? station; // 라디오 채널\n\n  ParanAlarm({\n    this.enabled = true,\n    this.hour = 7,\n    this.minute = 0,\n    List<int>? days,\n    this.kind = 'music_all',\n    this.refId,\n    this.label = '전체 곡 섞어 듣기',\n    this.station,\n  }) : days = days ?? [1, 2, 3, 4, 5];\n\n  ParanAlarm copy() => ParanAlarm(\n        enabled: enabled,\n        hour: hour,\n        minute: minute,\n        days: List.of(days),\n        kind: kind,\n        refId: refId,\n        label: label,\n        station: station == null ? null : Map<String, dynamic>.from(station!),\n      );\n\n  Map<String, dynamic> toJson() => {\n        'enabled': enabled,\n        'hour': hour,\n        'minute': minute,\n        'days': days,\n        'kind': kind,\n        'refId': refId,\n        'label': label,\n        'station': station,\n      };\n\n  factory ParanAlarm.fromJson(Map<String, dynamic> j) => ParanAlarm(\n        enabled: j['enabled'] == true,\n        hour: (j['hour'] as num?)?.toInt() ?? 7,\n        minute: (j['minute'] as num?)?.toInt() ?? 0,\n        days: [for (final d in (j['days'] as List? ?? const [])) (d as num).toInt()],\n        kind: j['kind']?.toString() ?? 'music_all',\n        refId: j['refId']?.toString(),\n        label: j['label']?.toString() ?? '전체 곡 섞어 듣기',\n        station: j['station'] is Map ? Map<String, dynamic>.from(j['station'] as Map) : null,\n      );\n}\n\n/// 아침 알람: 저장 · 폰 알람 시계에 예약 · 울릴 때 알람 화면 띄우기\nclass AlarmService {\n  static const _ch = MethodChannel('kr.ssing.catsong/alarm');\n  static const _key = 'paranAlarm';\n  static const _snoozeKey = 'paranAlarmSnooze';\n\n  /// 어느 화면에서든 알람 화면을 띄우기 위한 열쇠 (MaterialApp에 연결)\n  static final navKey = GlobalKey<NavigatorState>();\n\n  /// 지금 알람 (없으면 null) — 더보기 메뉴 카드가 이걸 보고 바뀜\n  static final ValueNotifier<ParanAlarm?> alarm = ValueNotifier(null);\n\n  /// 알람 때문에 앱이 켜졌는지 (첫인사·인트로 건너뛰기)\n  static bool launchedByAlarm = false;\n  static bool _ringing = false;\n\n  /// 앱 켤 때 한 번 (runApp 전에)\n  static Future<void> init() async {\n    _ch.setMethodCallHandler((call) async {\n      if (call.method == 'alarmFired') {\n        try {\n          await _ch.invokeMethod('takeLaunchAlarm'); // 다음에 켤 때 또 울리지 않게\n        } catch (_) {}\n        showRing();\n      }\n      return null;\n    });\n    try {\n      final p = await SharedPreferences.getInstance();\n      final s = p.getString(_key);\n      if (s != null) alarm.value = ParanAlarm.fromJson(jsonDecode(s) as Map<String, dynamic>);\n    } catch (_) {}\n    try {\n      launchedByAlarm = await _ch.invokeMethod('takeLaunchAlarm') == true;\n    } catch (_) {}\n    // 혹시 예약이 지워졌어도 다시 걸어두기 (울려서 켜진 거면 다음 알람으로)\n    final a = alarm.value;\n    if (a != null && a.enabled && !launchedByAlarm) _scheduleNext(a);\n  }\n\n  /// 다음에 울릴 시각 (꺼져 있거나 못 찾으면 null)\n  static DateTime? nextTime(ParanAlarm a, [DateTime? from]) {\n    if (!a.enabled) return null;\n    final now = from ?? DateTime.now();\n    for (var d = 0; d <= 7; d++) {\n      final t = DateTime(now.year, now.month, now.day + d, a.hour, a.minute);\n      if (t.isAfter(now) && (a.days.isEmpty || a.days.contains(t.weekday))) return t;\n    }\n    return null;\n  }\n\n  static const _dayNames = ['월', '화', '수', '목', '금', '토', '일'];\n\n  /// 예: 오전 7:00\n  static String timeText(int hour, int minute) {\n    final ampm = hour < 12 ? '오전' : '오후';\n    final h = hour % 12 == 0 ? 12 : hour % 12;\n    return '$ampm $h:${minute.toString().padLeft(2, '0')}';\n  }\n\n  /// 예: 내일 오전 7:00 / 월요일 오전 7:00\n  static String nextLabel(ParanAlarm a) {\n    final t = nextTime(a);\n    if (t == null) return '';\n    final now = DateTime.now();\n    final diff = DateTime(t.year, t.month, t.day).difference(DateTime(now.year, now.month, now.day)).inDays;\n    final day = diff == 0 ? '오늘' : (diff == 1 ? '내일' : '${_dayNames[t.weekday - 1]}요일');\n    return '$day ${timeText(t.hour, t.minute)}';\n  }\n\n  /// 예: 평일 · 주말 · 매일 · 한 번만 · 월 수 금\n  static String daysText(List<int> days) {\n    final s = days.toSet();\n    if (s.isEmpty) return '한 번만';\n    if (s.length == 7) return '매일';\n    if (s.length == 5 && s.containsAll([1, 2, 3, 4, 5])) return '평일';\n    if (s.length == 2 && s.containsAll([6, 7])) return '주말';\n    return [for (var d = 1; d <= 7; d++) if (s.contains(d)) _dayNames[d - 1]].join(' ');\n  }\n\n  static Future<bool> canExact() async {\n    try {\n      return await _ch.invokeMethod('canExact') != false;\n    } catch (_) {\n      return true;\n    }\n  }\n\n  static Future<void> openExactSettings() async {\n    try {\n      await _ch.invokeMethod('openExactSettings');\n    } catch (_) {}\n  }\n\n  /// 저장 + 예약. 권한(알람 및 리마인더)이 없으면 false\n  static Future<bool> save(ParanAlarm a) async {\n    alarm.value = a.copy();\n    final p = await SharedPreferences.getInstance();\n    await p.setString(_key, jsonEncode(a.toJson()));\n    await p.remove(_snoozeKey);\n    if (!a.enabled) {\n      await _cancel();\n      return true;\n    }\n    if (!await canExact()) return false;\n    return _scheduleNext(a);\n  }\n\n  static Future<bool> _scheduleNext(ParanAlarm a) async {\n    final p = await SharedPreferences.getInstance();\n    // 5분 뒤 다시가 남아 있으면 그게 먼저\n    final snooze = p.getInt(_snoozeKey) ?? 0;\n    final t = snooze > DateTime.now().millisecondsSinceEpoch\n        ? DateTime.fromMillisecondsSinceEpoch(snooze)\n        : nextTime(a);\n    if (t == null) {\n      await _cancel();\n      return true;\n    }\n    try {\n      return await _ch.invokeMethod('schedule', {'at': t.millisecondsSinceEpoch}) != false;\n    } catch (_) {\n      return false;\n    }\n  }\n\n  static Future<void> _cancel() async {\n    try {\n      await _ch.invokeMethod('cancel');\n    } catch (_) {}\n  }\n\n  /// 알람 화면 띄우기 (화면이 아직 준비 안 됐으면 조금 기다렸다가)\n  static Future<void> showRing() async {\n    if (_ringing) return;\n    _ringing = true;\n    for (var i = 0; i < 20 && navKey.currentState == null; i++) {\n      await Future.delayed(const Duration(milliseconds: 300));\n    }\n    final nav = navKey.currentState;\n    if (nav == null) {\n      _ringing = false;\n      return;\n    }\n    await nav.push(MaterialPageRoute(builder: (_) => const AlarmRingScreen(), fullscreenDialog: true));\n    _ringing = false;\n  }\n\n  /// [끄기] · [계속 듣기]: 한 번만이면 끄고, 반복이면 다음 알람 예약\n  static Future<void> dismiss() async {\n    try {\n      await _ch.invokeMethod('ringDone');\n    } catch (_) {}\n    final p = await SharedPreferences.getInstance();\n    await p.remove(_snoozeKey);\n    final a = alarm.value;\n    if (a == null) return;\n    if (a.days.isEmpty) {\n      a.enabled = false;\n      await save(a);\n    } else {\n      await _scheduleNext(a);\n    }\n  }\n\n  /// [5분 뒤 다시]\n  static Future<void> snooze() async {\n    try {\n      await _ch.invokeMethod('ringDone');\n    } catch (_) {}\n    final at = DateTime.now().add(const Duration(minutes: 5));\n    final p = await SharedPreferences.getInstance();\n    await p.setInt(_snoozeKey, at.millisecondsSinceEpoch);\n    try {\n      await _ch.invokeMethod('schedule', {'at': at.millisecondsSinceEpoch});\n    } catch (_) {}\n  }\n}\n", 'alarm_ring_screen.dart': "import 'dart:async';\nimport 'dart:math' as math;\nimport 'package:flutter/material.dart';\nimport 'package:flutter/services.dart';\nimport 'package:provider/provider.dart';\nimport '../models/radio_station.dart';\nimport '../models/song.dart';\nimport '../providers/music_provider.dart';\nimport '../providers/player_provider.dart';\nimport '../providers/playlist_provider.dart';\nimport '../providers/radio_provider.dart';\nimport '../services/alarm_service.dart';\n\n/// 알람이 울릴 때 화면 (잠금화면 위로 뜸)\n/// 고른 소리를 작게 시작해서 30초쯤 동안 천천히 키움\nclass AlarmRingScreen extends StatefulWidget {\n  const AlarmRingScreen({super.key});\n\n  @override\n  State<AlarmRingScreen> createState() => _AlarmRingScreenState();\n}\n\nclass _AlarmRingScreenState extends State<AlarmRingScreen> {\n  static const _bg1 = Color(0xFF2B2926);\n  static const _bg2 = Color(0xFF1C1A17);\n  static const _cream = Color(0xFFF3EFE7);\n  static const _ink = Color(0xFF17140F);\n  static const _sub = Color(0xFFB8B0A2);\n  static const _days = ['월', '화', '수', '목', '금', '토', '일'];\n\n  Timer? _clock;\n  Timer? _fade;\n  double _vol = 0.15;\n  bool _radio = false; // 라디오로 울리는 중\n  bool _nature = false; // 자연으로 울리는 중\n  bool _done = false;\n  late final ParanAlarm _a = AlarmService.alarm.value?.copy() ?? ParanAlarm();\n\n  @override\n  void initState() {\n    super.initState();\n    _clock = Timer.periodic(const Duration(seconds: 1), (_) {\n      if (mounted) setState(() {});\n    });\n    WidgetsBinding.instance.addPostFrameCallback((_) => _start());\n  }\n\n  @override\n  void dispose() {\n    _clock?.cancel();\n    _fade?.cancel();\n    super.dispose();\n  }\n\n  // ───── 소리 ─────\n\n  Future<void> _setVol(double v) async {\n    try {\n      if (_radio) {\n        await context.read<RadioProvider>().setAlarmVolume(v);\n      } else {\n        await context.read<PlayerProvider>().player.setVolume(v);\n      }\n    } catch (_) {}\n  }\n\n  /// 노래 목록 기다리기 (알람으로 앱이 막 켜졌으면 곡을 불러오는 중이라)\n  Future<List<Song>> _songs() async {\n    final music = context.read<MusicProvider>();\n    final pl = context.read<PlaylistProvider>();\n    for (var i = 0; i < 20 && music.allSongs.isEmpty; i++) {\n      await Future.delayed(const Duration(milliseconds: 500));\n    }\n    if (!mounted) return const [];\n    List<Song> list = music.allSongs;\n    if (_a.kind == 'music_fav') {\n      list = music.favorites;\n    } else if (_a.kind == 'playlist') {\n      for (var i = 0; i < 10; i++) {\n        final found = pl.playlists.where((p) => p.id == _a.refId);\n        if (found.isNotEmpty && found.first.songs.isNotEmpty) {\n          list = found.first.songs;\n          break;\n        }\n        await Future.delayed(const Duration(milliseconds: 500));\n      }\n    }\n    if (list.isEmpty) list = music.allSongs; // 비어 있으면 전체 곡으로\n    return List<Song>.from(list)..shuffle();\n  }\n\n  Future<void> _start() async {\n    final player = context.read<PlayerProvider>();\n    final radio = context.read<RadioProvider>();\n    var ok = false;\n    try {\n      if (_a.kind == 'radio' && _a.station != null) {\n        _radio = true;\n        await _setVol(_vol);\n        final st = RadioStation.fromJson(Map<String, dynamic>.from(_a.station!));\n        radio.setQueue([st], 0);\n        await radio.playStation(st);\n        ok = true;\n        // 15초 지나도 안 나오면 (인터넷 문제) 폰에 있는 노래로\n        Future.delayed(const Duration(seconds: 15), () {\n          if (mounted && !_done && _radio && !radio.isPlaying) _fallback();\n        });\n      } else if (_a.kind == 'nature') {\n        _nature = true;\n        await _setVol(_vol);\n        final n = PlayerProvider.natureSoundOrder.firstWhere((m) => m['name'] == _a.refId,\n            orElse: () => PlayerProvider.natureSoundOrder.firstWhere((m) => m['name'] == '새소리'));\n        await player.playNatureSound(n['assetPath']!, n['name']!);\n        ok = true;\n      } else {\n        final songs = await _songs();\n        if (!mounted || _done) return;\n        if (songs.isNotEmpty) {\n          await _setVol(_vol);\n          await player.playFromList(songs, 0);\n          ok = true;\n        }\n      }\n    } catch (_) {}\n    if (!ok && mounted && !_done) await _fallback();\n    // 30초쯤 동안 천천히 크게\n    _fade = Timer.periodic(const Duration(seconds: 1), (t) {\n      _vol = math.min(1.0, _vol + 0.03);\n      _setVol(_vol);\n      if (_vol >= 1.0) t.cancel();\n    });\n  }\n\n  /// 원래 소리가 안 될 때: 폰에 있는 노래 → 그것도 없으면 새소리\n  Future<void> _fallback() async {\n    final player = context.read<PlayerProvider>();\n    if (_radio) {\n      try {\n        await context.read<RadioProvider>().stopRadioAndClear();\n        await context.read<RadioProvider>().setAlarmVolume(1.0);\n      } catch (_) {}\n      _radio = false;\n    }\n    await _setVol(_vol);\n    final all = List<Song>.from(context.read<MusicProvider>().allSongs)..shuffle();\n    try {\n      if (all.isNotEmpty) {\n        _nature = false;\n        await player.playFromList(all, 0);\n      } else {\n        _nature = true;\n        final n = PlayerProvider.natureSoundOrder.firstWhere((m) => m['name'] == '새소리');\n        await player.playNatureSound(n['assetPath']!, n['name']!);\n      }\n    } catch (_) {}\n  }\n\n  Future<void> _stopSound() async {\n    final player = context.read<PlayerProvider>();\n    try {\n      if (_radio) {\n        await context.read<RadioProvider>().stopRadioAndClear();\n      } else if (_nature) {\n        await player.stopNatureSound();\n      } else {\n        await player.player.pause();\n      }\n    } catch (_) {}\n  }\n\n  /// 소리 크기 원래대로 (다음에 들을 때 작게 나오지 않게)\n  Future<void> _restoreVol() async {\n    try {\n      await context.read<PlayerProvider>().player.setVolume(1.0);\n      await context.read<RadioProvider>().setAlarmVolume(1.0);\n    } catch (_) {}\n  }\n\n  // ───── 버튼 ─────\n\n  Future<void> _off() async {\n    if (_done) return;\n    _done = true;\n    HapticFeedback.mediumImpact();\n    _fade?.cancel();\n    await _stopSound();\n    await _restoreVol();\n    await AlarmService.dismiss();\n    if (mounted) Navigator.pop(context);\n  }\n\n  Future<void> _later() async {\n    if (_done) return;\n    _done = true;\n    HapticFeedback.mediumImpact();\n    _fade?.cancel();\n    await _stopSound();\n    await _restoreVol();\n    await AlarmService.snooze();\n    if (mounted) Navigator.pop(context);\n  }\n\n  Future<void> _keep() async {\n    if (_done) return;\n    _done = true;\n    _fade?.cancel();\n    await _restoreVol(); // 소리는 그대로, 크기만 원래대로\n    await AlarmService.dismiss();\n    if (mounted) Navigator.pop(context);\n  }\n\n  IconData get _icon {\n    if (_a.kind == 'radio') return Icons.radio_rounded;\n    if (_a.kind == 'nature') return Icons.forest_outlined;\n    if (_a.kind == 'playlist') return Icons.queue_music_rounded;\n    if (_a.kind == 'music_fav') return Icons.favorite_border_rounded;\n    return Icons.shuffle_rounded;\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final now = DateTime.now();\n    final h = now.hour % 12 == 0 ? 12 : now.hour % 12;\n    final ampm = now.hour < 12 ? '오전' : '오후';\n    final greet = now.hour < 12 ? '좋은 아침이에요' : '알람 시간이에요';\n    return PopScope(\n      canPop: false, // 뒤로가기로 실수로 닫히지 않게\n      child: AnnotatedRegion<SystemUiOverlayStyle>(\n        value: const SystemUiOverlayStyle(\n          statusBarColor: Colors.transparent,\n          statusBarIconBrightness: Brightness.light,\n          systemNavigationBarColor: _bg2,\n          systemNavigationBarIconBrightness: Brightness.light,\n        ),\n        child: Scaffold(\n          backgroundColor: _bg2,\n          body: Container(\n            decoration: const BoxDecoration(\n              gradient: LinearGradient(\n                begin: Alignment.topCenter,\n                end: Alignment.bottomCenter,\n                colors: [_bg1, _bg2],\n              ),\n            ),\n            child: SafeArea(\n              child: Padding(\n                padding: const EdgeInsets.fromLTRB(24, 0, 24, 16),\n                child: Column(\n                  children: [\n                    const Spacer(flex: 3),\n                    Text(greet,\n                        style: TextStyle(\n                            color: _cream.withOpacity(0.75), fontSize: 16, fontWeight: FontWeight.w500)),\n                    const SizedBox(height: 10),\n                    Row(\n                      mainAxisAlignment: MainAxisAlignment.center,\n                      crossAxisAlignment: CrossAxisAlignment.baseline,\n                      textBaseline: TextBaseline.alphabetic,\n                      children: [\n                        Text(ampm,\n                            style: const TextStyle(color: _sub, fontSize: 18, fontWeight: FontWeight.w500)),\n                        const SizedBox(width: 6),\n                        Text('$h:${now.minute.toString().padLeft(2, '0')}',\n                            style: const TextStyle(\n                                color: _cream,\n                                fontSize: 72,\n                                fontWeight: FontWeight.w300,\n                                letterSpacing: -1.5,\n                                height: 1.1)),\n                      ],\n                    ),\n                    const SizedBox(height: 6),\n                    Text('${now.month}월 ${now.day}일 ${_days[now.weekday - 1]}요일',\n                        style: const TextStyle(color: _sub, fontSize: 15)),\n                    const Spacer(flex: 2),\n                    // 깨우는 소리\n                    Container(\n                      padding: const EdgeInsets.fromLTRB(14, 10, 16, 10),\n                      decoration: BoxDecoration(\n                        color: Colors.white.withOpacity(0.06),\n                        borderRadius: BorderRadius.circular(16),\n                        border: Border.all(color: Colors.white.withOpacity(0.08)),\n                      ),\n                      child: Row(\n                        mainAxisSize: MainAxisSize.min,\n                        children: [\n                          Icon(_icon, size: 18, color: _sub),\n                          const SizedBox(width: 8),\n                          Flexible(\n                            child: Text(_a.label,\n                                maxLines: 1,\n                                overflow: TextOverflow.ellipsis,\n                                style: const TextStyle(color: _cream, fontSize: 14, fontWeight: FontWeight.w600)),\n                          ),\n                        ],\n                      ),\n                    ),\n                    const Spacer(flex: 3),\n                    SizedBox(\n                      width: double.infinity,\n                      height: 58,\n                      child: ElevatedButton(\n                        onPressed: _off,\n                        style: ElevatedButton.styleFrom(\n                          backgroundColor: _cream,\n                          foregroundColor: _ink,\n                          elevation: 0,\n                          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(18)),\n                        ),\n                        child: const Text('끄기', style: TextStyle(fontSize: 17, fontWeight: FontWeight.w700)),\n                      ),\n                    ),\n                    const SizedBox(height: 10),\n                    SizedBox(\n                      width: double.infinity,\n                      height: 54,\n                      child: OutlinedButton(\n                        onPressed: _later,\n                        style: OutlinedButton.styleFrom(\n                          foregroundColor: _cream,\n                          side: BorderSide(color: _cream.withOpacity(0.3), width: 1.2),\n                          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(18)),\n                        ),\n                        child: const Text('5분 뒤 다시', style: TextStyle(fontSize: 15.5, fontWeight: FontWeight.w600)),\n                      ),\n                    ),\n                    const SizedBox(height: 6),\n                    TextButton(\n                      onPressed: _keep,\n                      style: TextButton.styleFrom(foregroundColor: _sub),\n                      child: const Text('알람 끄고 계속 듣기', style: TextStyle(fontSize: 13.5)),\n                    ),\n                  ],\n                ),\n              ),\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n}\n", 'alarm_screen.dart': 'import \'package:flutter/cupertino.dart\';\nimport \'package:flutter/material.dart\';\nimport \'package:flutter/services.dart\';\nimport \'package:provider/provider.dart\';\nimport \'../providers/player_provider.dart\';\nimport \'../providers/playlist_provider.dart\';\nimport \'../providers/radio_provider.dart\';\nimport \'../providers/theme_provider.dart\';\nimport \'../services/alarm_service.dart\';\nimport \'../widgets/paran_dialog.dart\';\nimport \'../widgets/paran_toast.dart\';\n\n/// 아침 알람 맞추기 (더보기 메뉴에서)\nclass AlarmScreen extends StatefulWidget {\n  const AlarmScreen({super.key});\n\n  @override\n  State<AlarmScreen> createState() => _AlarmScreenState();\n}\n\nclass _AlarmScreenState extends State<AlarmScreen> {\n  late ParanAlarm _a = AlarmService.alarm.value?.copy() ?? ParanAlarm();\n  static const _dayNames = [\'월\', \'화\', \'수\', \'목\', \'금\', \'토\', \'일\'];\n\n  void _vib() => const MethodChannel(\'kr.ssing.catsong/media\').invokeMethod(\'vibrate\');\n\n  // ───── 깨울 소리 고르기 ─────\n\n  void _pickMusic(String kind, String label) {\n    _vib();\n    setState(() {\n      _a.kind = kind;\n      _a.label = label;\n      _a.refId = null;\n      _a.station = null;\n    });\n  }\n\n  void _pickPlaylist() {\n    final lists = context.read<PlaylistProvider>().playlists;\n    if (lists.isEmpty) {\n      showParanToast(context, \'재생목록을 먼저 만들어 주세요\');\n      return;\n    }\n    showParanSheet(\n      context,\n      title: \'재생목록 고르기\',\n      builder: (ctx, setSheet) => ParanCard(\n        children: [\n          for (final p in lists)\n            ParanRow(\n              icon: Icons.queue_music_rounded,\n              title: p.name,\n              trailingText: \'${p.songs.length}곡\',\n              selected: _a.kind == \'playlist\' && _a.refId == p.id,\n              onTap: () {\n                setState(() {\n                  _a.kind = \'playlist\';\n                  _a.refId = p.id;\n                  _a.label = p.name;\n                  _a.station = null;\n                });\n                Navigator.pop(ctx);\n              },\n            ),\n        ],\n      ),\n    );\n  }\n\n  void _pickRadio() {\n    final favs = context.read<RadioProvider>().favorites;\n    if (favs.isEmpty) {\n      showParanToast(context, \'라디오 즐겨찾기에 채널을 먼저 담아 주세요\');\n      return;\n    }\n    showParanSheet(\n      context,\n      title: \'라디오 채널 고르기\',\n      builder: (ctx, setSheet) => ParanCard(\n        children: [\n          for (final s in favs)\n            ParanRow(\n              icon: Icons.radio_rounded,\n              title: s.name,\n              selected: _a.kind == \'radio\' && _a.refId == s.stationUuid,\n              onTap: () {\n                setState(() {\n                  _a.kind = \'radio\';\n                  _a.refId = s.stationUuid;\n                  _a.label = s.name;\n                  _a.station = s.toJson();\n                });\n                Navigator.pop(ctx);\n              },\n            ),\n        ],\n      ),\n    );\n  }\n\n  void _pickNature() {\n    showParanSheet(\n      context,\n      title: \'자연 소리 고르기\',\n      builder: (ctx, setSheet) => ParanCard(\n        children: [\n          for (final n in PlayerProvider.natureSoundOrder)\n            ParanRow(\n              icon: Icons.forest_outlined,\n              title: n[\'name\']!,\n              selected: _a.kind == \'nature\' && _a.refId == n[\'name\'],\n              onTap: () {\n                setState(() {\n                  _a.kind = \'nature\';\n                  _a.refId = n[\'name\'];\n                  _a.label = n[\'name\']!;\n                  _a.station = null;\n                });\n                Navigator.pop(ctx);\n              },\n            ),\n        ],\n      ),\n    );\n  }\n\n  // ───── 저장 ─────\n\n  Future<void> _save() async {\n    _vib();\n    final ok = await AlarmService.save(_a);\n    if (!mounted) return;\n    if (!ok) {\n      final go = await showParanConfirm(\n        context,\n        title: \'알람 권한이 필요해요\',\n        message: \'정해진 시간에 깨우려면 "알람 및 리마인더"를 허용해 주세요. 허용한 뒤 다시 저장을 눌러 주세요.\',\n        confirmLabel: \'설정 열기\',\n      );\n      if (go) AlarmService.openExactSettings();\n      return;\n    }\n    showParanToast(context, _a.enabled ? \'${AlarmService.nextLabel(_a)}에 깨워 드릴게요\' : \'알람을 껐어요\');\n    Navigator.pop(context);\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final theme = context.watch<ThemeProvider>();\n    final d = theme.isDarkMode;\n    final point = theme.primaryColor;\n    final bg = d ? const Color(0xFF24221F) : const Color(0xFFF4EFE5);\n    final card = d ? const Color(0xFF32302C) : Colors.white;\n    final ink = d ? const Color(0xFFF3EFE7) : const Color(0xFF17140F);\n    final onInk = d ? const Color(0xFF17140F) : const Color(0xFFF4EFE5);\n    final hint = d ? const Color(0xFFB8B0A2) : const Color(0xFF8A8378);\n    final line = d ? const Color(0xFF4A4640) : const Color(0xFFEEE9DF);\n    final iconBg = d ? Colors.white.withOpacity(0.08) : const Color(0xFFF4EFE5);\n\n    Widget box(List<Widget> children, {EdgeInsets? padding}) => Container(\n          margin: const EdgeInsets.only(bottom: 12),\n          padding: padding ?? const EdgeInsets.fromLTRB(16, 14, 16, 14),\n          decoration: BoxDecoration(color: card, borderRadius: BorderRadius.circular(16)),\n          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: children),\n        );\n\n    Widget head(String t, [String? right]) => Row(\n          children: [\n            Text(t, style: TextStyle(color: ink, fontSize: 14.5, fontWeight: FontWeight.w600)),\n            const Spacer(),\n            if (right != null) Text(right, style: TextStyle(color: hint, fontSize: 12.5)),\n          ],\n        );\n\n    // 깨울 소리 한 줄\n    Widget soundRow(IconData icon, String title, bool selected, VoidCallback onTap, {String? sub, bool more = false}) =>\n        InkWell(\n          onTap: onTap,\n          child: Padding(\n            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 11),\n            child: Row(\n              children: [\n                Container(\n                  width: 30,\n                  height: 30,\n                  decoration: BoxDecoration(color: iconBg, borderRadius: BorderRadius.circular(9)),\n                  child: Icon(icon, size: 17, color: hint),\n                ),\n                const SizedBox(width: 12),\n                Expanded(\n                  child: Column(\n                    crossAxisAlignment: CrossAxisAlignment.start,\n                    children: [\n                      Text(title,\n                          style: TextStyle(\n                              color: ink,\n                              fontSize: 14.5,\n                              fontWeight: selected ? FontWeight.w700 : FontWeight.w500)),\n                      if (sub != null) ...[\n                        const SizedBox(height: 2),\n                        Text(sub,\n                            maxLines: 1,\n                            overflow: TextOverflow.ellipsis,\n                            style: TextStyle(color: hint, fontSize: 12)),\n                      ],\n                    ],\n                  ),\n                ),\n                const SizedBox(width: 8),\n                if (selected)\n                  Icon(Icons.check_circle_rounded, size: 20, color: point)\n                else if (more)\n                  Icon(Icons.chevron_right_rounded, size: 20, color: hint),\n              ],\n            ),\n          ),\n        );\n\n    final next = AlarmService.nextLabel(_a);\n\n    return Scaffold(\n      backgroundColor: bg,\n      appBar: AppBar(\n        backgroundColor: bg,\n        elevation: 0,\n        scrolledUnderElevation: 0,\n        title: Text(\'아침 알람\',\n            style: TextStyle(color: ink, fontSize: 17, fontWeight: FontWeight.w600, letterSpacing: -0.3)),\n        leading: IconButton(\n          onPressed: () => Navigator.pop(context),\n          icon: Icon(Icons.arrow_back_ios, color: ink, size: 20),\n        ),\n        bottom: PreferredSize(preferredSize: const Size.fromHeight(1), child: Divider(height: 1, color: line)),\n      ),\n      body: SafeArea(\n        top: false,\n        child: ListView(\n          padding: const EdgeInsets.fromLTRB(16, 14, 16, 16),\n          children: [\n            // 켜기·끄기\n            box([\n              Row(\n                children: [\n                  Expanded(\n                    child: Column(\n                      crossAxisAlignment: CrossAxisAlignment.start,\n                      children: [\n                        Text(\'알람\', style: TextStyle(color: ink, fontSize: 15, fontWeight: FontWeight.w600)),\n                        const SizedBox(height: 2),\n                        Text(_a.enabled ? \'$next에 울려요\' : \'꺼져 있어요\',\n                            style: TextStyle(color: hint, fontSize: 12.5)),\n                      ],\n                    ),\n                  ),\n                  Switch(\n                    value: _a.enabled,\n                    activeColor: point,\n                    onChanged: (v) {\n                      _vib();\n                      setState(() => _a.enabled = v);\n                    },\n                  ),\n                ],\n              ),\n            ], padding: const EdgeInsets.fromLTRB(16, 8, 8, 8)),\n            // 시간\n            Opacity(\n              opacity: _a.enabled ? 1 : 0.45,\n              child: IgnorePointer(\n                ignoring: !_a.enabled,\n                child: Column(\n                  children: [\n                    box([\n                      head(\'시간\'),\n                      SizedBox(\n                        height: 170,\n                        child: CupertinoTheme(\n                          data: CupertinoThemeData(\n                            brightness: d ? Brightness.dark : Brightness.light,\n                            textTheme: CupertinoTextThemeData(\n                              dateTimePickerTextStyle: TextStyle(color: ink, fontSize: 22),\n                            ),\n                          ),\n                          child: CupertinoDatePicker(\n                            mode: CupertinoDatePickerMode.time,\n                            initialDateTime: DateTime(2000, 1, 1, _a.hour, _a.minute),\n                            onDateTimeChanged: (t) => setState(() {\n                              _a.hour = t.hour;\n                              _a.minute = t.minute;\n                            }),\n                          ),\n                        ),\n                      ),\n                    ]),\n                    // 반복 요일\n                    box([\n                      head(\'반복\', AlarmService.daysText(_a.days)),\n                      const SizedBox(height: 12),\n                      Row(\n                        mainAxisAlignment: MainAxisAlignment.spaceBetween,\n                        children: [\n                          for (var i = 1; i <= 7; i++)\n                            GestureDetector(\n                              onTap: () {\n                                _vib();\n                                setState(() {\n                                  _a.days.contains(i) ? _a.days.remove(i) : _a.days.add(i);\n                                  _a.days.sort();\n                                });\n                              },\n                              child: AnimatedContainer(\n                                duration: const Duration(milliseconds: 150),\n                                width: 38,\n                                height: 38,\n                                alignment: Alignment.center,\n                                decoration: BoxDecoration(\n                                  shape: BoxShape.circle,\n                                  color: _a.days.contains(i) ? ink : Colors.transparent,\n                                  border: Border.all(color: _a.days.contains(i) ? ink : line, width: 1.2),\n                                ),\n                                child: Text(_dayNames[i - 1],\n                                    style: TextStyle(\n                                        color: _a.days.contains(i) ? onInk : ink,\n                                        fontSize: 13.5,\n                                        fontWeight: FontWeight.w600)),\n                              ),\n                            ),\n                        ],\n                      ),\n                      const SizedBox(height: 10),\n                      Text(\'요일을 하나도 안 고르면 한 번만 울려요\', style: TextStyle(color: hint, fontSize: 12)),\n                    ]),\n                    // 깨울 소리\n                    box([\n                      Padding(\n                        padding: const EdgeInsets.fromLTRB(16, 0, 16, 4),\n                        child: head(\'깨울 소리\'),\n                      ),\n                      soundRow(Icons.shuffle_rounded, \'전체 곡 섞어 듣기\', _a.kind == \'music_all\',\n                          () => _pickMusic(\'music_all\', \'전체 곡 섞어 듣기\')),\n                      soundRow(Icons.favorite_border_rounded, \'즐겨찾기 섞어 듣기\', _a.kind == \'music_fav\',\n                          () => _pickMusic(\'music_fav\', \'즐겨찾기 섞어 듣기\')),\n                      soundRow(Icons.queue_music_rounded, \'재생목록\', _a.kind == \'playlist\', _pickPlaylist,\n                          sub: _a.kind == \'playlist\' ? _a.label : null, more: true),\n                      soundRow(Icons.radio_rounded, \'라디오\', _a.kind == \'radio\', _pickRadio,\n                          sub: _a.kind == \'radio\' ? _a.label : \'즐겨찾기한 채널\', more: true),\n                      soundRow(Icons.forest_outlined, \'자연\', _a.kind == \'nature\', _pickNature,\n                          sub: _a.kind == \'nature\' ? _a.label : \'새소리 · 시냇물 · 파도\', more: true),\n                      Padding(\n                        padding: const EdgeInsets.fromLTRB(16, 6, 16, 0),\n                        child: Text(\'작은 소리로 시작해서 30초 동안 천천히 커져요\',\n                            style: TextStyle(color: hint, fontSize: 12)),\n                      ),\n                    ], padding: const EdgeInsets.fromLTRB(0, 14, 0, 14)),\n                  ],\n                ),\n              ),\n            ),\n          ],\n        ),\n      ),\n      bottomNavigationBar: SafeArea(\n        top: false,\n        child: Padding(\n          padding: const EdgeInsets.fromLTRB(16, 4, 16, 12),\n          child: SizedBox(\n            height: 54,\n            child: ElevatedButton(\n              onPressed: _save,\n              style: ElevatedButton.styleFrom(\n                backgroundColor: ink,\n                foregroundColor: onInk,\n                elevation: 0,\n                shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),\n              ),\n              child: const Text(\'저장\', style: TextStyle(fontSize: 16, fontWeight: FontWeight.w700)),\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n}\n'}
