def balanced(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    st = []
    for ch in s:
        if ch in '([{':
            st.append(ch)
        elif ch in ')]}':
            if not st or st.pop() != pairs[ch]:
                return False
    return not st


def find_activity():
    hits = glob.glob(os.path.join(ROOT, 'android', 'app', 'src', 'main', 'kotlin', '**', 'MainActivity.kt'),
                     recursive=True)
    return hits[0] if len(hits) == 1 else None


def main():
    act = find_activity()
    for p in (MAIN, RADIO, MORE, MANIFEST):
        if not os.path.exists(p):
            print('❌ 파일을 못 찾았어요:', p)
            sys.exit(1)
    if act is None:
        print('❌ MainActivity.kt 를 못 찾았어요 (android/app/src/main/kotlin 안)')
        sys.exit(1)
    if 'AlarmService' in open(MAIN, 'rb').read().decode('utf-8'):
        print('이미 적용돼 있어요')
        return
    for name, path in NEW_PATHS.items():
        if os.path.exists(path):
            print('❌ 이미 같은 이름 파일이 있어요:', os.path.relpath(path, ROOT))
            print('\n아무것도 저장하지 않았어요.')
            sys.exit(1)

    out = []
    ok = True
    check_brackets = (MAIN, RADIO, MORE, act)
    for path, edits in ((MAIN, MAIN_EDITS), (RADIO, RADIO_EDITS), (MORE, MORE_EDITS),
                        (act, KT_EDITS), (MANIFEST, MANIFEST_EDITS)):
        raw = open(path, 'rb').read().decode('utf-8')
        crlf = '\r\n' in raw
        text = raw.replace('\r\n', '\n')
        before = balanced(text)
        for name, old, new in edits:
            if text.count(old) != 1:
                print('❌', name, '(찾을 코드를 못 찾았어요)')
                ok = False
                continue
            text = text.replace(old, new)
            print('✔', name)
        if path in check_brackets and before and not balanced(text):
            print('❌ 괄호가 안 맞아요:', os.path.basename(path))
            ok = False
        out.append((path, text.replace('\n', '\r\n') if crlf else text))
    for name, content in NEW_FILES.items():
        if not balanced(content):
            print('❌ 괄호가 안 맞아요:', name)
            ok = False
    if not ok:
        print('\n아무것도 저장하지 않았어요.')
        sys.exit(1)
    for path, text in out:
        open(path, 'wb').write(text.encode('utf-8'))
    for name, content in NEW_FILES.items():
        open(NEW_PATHS[name], 'wb').write(content.encode('utf-8'))
        print('✔ 새 파일:', os.path.relpath(NEW_PATHS[name], ROOT).replace('\\', '/'))
    print('\n다 바꿨어요. 앱을 완전히 끄고 flutter run 으로 다시 켜 주세요 (안드로이드 쪽도 바뀌어서).')


if __name__ == '__main__':
    main()
